head.b:skin:
/*
 * Theme Name: PureSlate Studio Pro (v5.0 - Production Locked Version)
 * Description: Ruang kerja narasi terintegrasi dengan manajemen karakter dinamis, pengunci panel, dan penyimpanan lokal.
 */

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap');

:root {
    --bg-main: #0b0f19;
    --bg-sidebar: #0f1626;
    --bg-card: #141b2d;
    --bg-input: #1f293d;
    --border-color: #24324f;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --accent-blue: #38bdf8;
    --accent-green: #10b981;
    --accent-purple: #a855f7;
    --accent-rose: #f43f5e;
}

*, *::before, *::after { box-sizing: border-box; }
body, html {
    margin: 0; padding: 0;
    background-color: var(--bg-main);
    color: var(--text-main);
    font-family: 'Plus Jakarta Sans', sans-serif;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

/* Layout Framework */
.dashboard-container {
    display: grid;
    grid-template-columns: 280px 1fr;
    min-height: 100vh;
}

@media (max-width: 1024px) {
    .dashboard-container { grid-template-columns: 1fr; }
    .sidebar { height: auto !important; position: relative !important; border-right: none !important; border-bottom: 1px solid var(--border-color); }
}

/* Sidebar Layout */
.sidebar {
    background: var(--bg-sidebar);
    border-right: 1px solid var(--border-color);
    padding: 32px 24px;
    display: flex;
    flex-direction: column;
    gap: 32px;
    position: sticky;
    top: 0;
    height: 100vh;
    overflow-y: auto;
}

.brand-section { display: flex; align-items: center; gap: 12px; }
.brand-logo {
    width: 32px; height: 32px;
    background: linear-gradient(135deg, var(--accent-purple), var(--accent-blue));
    border-radius: 8px;
}
.brand-name a {
    font-size: 18px;
    font-weight: 700;
    color: var(--text-main); text-decoration: none;
    letter-spacing: -0.5px;
}

/* Navigasi Menu */
.nav-menu { display: flex; flex-direction: column; gap: 8px; }
.nav-item {
    display: flex;
    align-items: center; gap: 12px;
    padding: 12px 14px; border-radius: 8px;
    color: var(--text-muted); font-size: 14px; font-weight: 500;
    cursor: pointer; transition: all 0.2s;
    text-decoration: none;
    border: none; background: none; width: 100%; text-align: left;
    font-family: inherit;
}
.nav-item:hover, .nav-item.active {
    background: rgba(168, 85, 247, 0.08);
    color: var(--accent-purple);
}

.system-status {
    margin-top: auto;
    background: rgba(168, 85, 247, 0.05);
    border: 1px solid rgba(168, 85, 247, 0.15);
    border-radius: 8px; padding: 12px;
    display: flex; align-items: center; gap: 10px;
    font-size: 12px; color: var(--accent-purple);
}
.status-pulse {
    width: 8px; height: 8px; background: var(--accent-purple);
    border-radius: 50%; box-shadow: 0 0 8px var(--accent-purple);
}

/* Main Workspace */
.main-workspace { padding: 40px; overflow-y: auto; }

.workspace-header {
    display: flex;
    justify-content: space-between; align-items: center;
    margin-bottom: 32px; border-bottom: 1px solid var(--border-color);
    padding-bottom: 24px; flex-wrap: wrap; gap: 20px;
}
.workspace-title h1 { font-size: 26px; margin: 0 0 4px 0; letter-spacing: -0.5px; }
.workspace-title p { margin: 0; color: var(--text-muted); font-size: 14px; }

.quick-stats { display: flex; align-items: center; gap: 14px; }
.stat-badge {
    background: var(--bg-card); border: 1px solid var(--border-color);
    padding: 8px 16px; border-radius: 8px; font-size: 12px;
}

.btn-zen {
    background: rgba(56, 189, 248, 0.1);
    border: 1px solid rgba(56, 189, 248, 0.2);
    color: var(--accent-blue);
    padding: 8px 16px; border-radius: 8px; font-size: 12px; font-weight: 600;
    cursor: pointer; transition: all 0.2s;
}
.btn-zen:hover { background: rgba(56, 189, 248, 0.2); }

/* Grid Layout */
.workspace-grid-system {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
}
@media (max-width: 900px) { .workspace-grid-system { grid-template-columns: 1fr; } }

/* Modifikasi Zen Mode */
body.zen-mode-active .sidebar { display: none !important; }
body.zen-mode-active .dashboard-container { grid-template-columns: 1fr; }
body.zen-mode-active .config-panel-section { display: none !important; }

/* Tab Panels Engine */
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* Control Panel Boxes */
.panel-box {
    background: var(--bg-card); border: 1px solid var(--border-color);
    border-radius: 16px; padding: 28px; min-height: 540px; display: flex; flex-direction: column; justify-content: space-between; gap: 20px;
}

.panel-header-row {
    display: flex; justify-content: space-between; align-items: center;
}
.panel-box h2 { font-size: 18px; margin: 0; display: flex; align-items: center; gap: 8px; color: var(--accent-purple); }

/* Tombol Kontrol Edit / Save */
.panel-actions { display: flex; gap: 8px; }
.btn-control-small {
    padding: 6px 12px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer; transition: all 0.2s;
}
.btn-edit { background: rgba(56, 189, 248, 0.1); border: 1px solid rgba(56, 189, 248, 0.2); color: var(--accent-blue); }
.btn-edit:hover { background: rgba(56, 189, 248, 0.2); }
.btn-save { background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.2); color: var(--accent-green); display: none; }
.btn-save:hover { background: rgba(16, 185, 129, 0.2); }

.panel-content-wrapper { display: flex; flex-direction: column; gap: 16px; }
.form-group { display: flex; flex-direction: column; gap: 8px; }
.form-label { display: block; font-size: 13px; font-weight: 600; color: var(--text-muted); }

.form-control {
    width: 100%; background: var(--bg-main); border: 1px solid var(--border-color);
    border-radius: 8px; padding: 12px 14px; color: var(--text-main);
    font-size: 14px; transition: all 0.2s; font-family: inherit;
}
.form-control:focus { border-color: var(--accent-purple); outline: none; }
.form-control:disabled { background: rgba(11, 15, 25, 0.4); color: #64748b; cursor: not-allowed; border-color: transparent; }
textarea.form-control { resize: vertical; min-height: 100px; }

/* Repeater List Manajemen Karakter */
.character-list-builder { display: flex; flex-direction: column; gap: 12px; max-height: 320px; overflow-y: auto; padding-right: 4px; }
.character-row-item {
    display: grid; grid-template-columns: 1fr 1.5fr auto; gap: 10px; align-items: center;
    background: rgba(11, 15, 25, 0.3); padding: 10px; border-radius: 8px; border: 1px solid var(--border-color);
}
.btn-delete-char {
    background: rgba(244, 63, 94, 0.1); border: 1px solid rgba(244, 63, 94, 0.2); color: var(--accent-rose);
    width: 38px; height: 38px; border-radius: 8px; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 14px;
}
.btn-delete-char:hover { background: rgba(244, 63, 94, 0.2); }
.btn-delete-char:disabled { opacity: 0.3; cursor: not-allowed; }

.btn-add-char-trigger {
    background: rgba(168, 85, 247, 0.1); border: 1px dashed rgba(168, 85, 247, 0.4); color: var(--accent-purple);
    padding: 10px; border-radius: 8px; font-size: 13px; font-weight: 600; cursor: pointer; text-align: center; transition: all 0.2s;
}
.btn-add-char-trigger:hover { background: rgba(168, 85, 247, 0.18); }
.btn-add-char-trigger:disabled { display: none; }

.btn-action-primary {
    width: 100%; background: linear-gradient(135deg, #a855f7 0%, #7e22ce 100%);
    border: none; color: #fff; padding: 14px; border-radius: 8px;
    font-weight: 600; font-size: 14px; cursor: pointer; transition: opacity 0.2s; margin-top: auto;
}
.btn-action-primary:hover { opacity: 0.9; }

/* Output Render Preview Terminal */
.output-preview-container { display: flex; flex-direction: column; gap: 20px; }
.terminal-header {
    background: #1e293b; border: 1px solid var(--border-color);
    border-top-left-radius: 12px; border-top-right-radius: 12px;
    padding: 12px 16px; display: flex; justify-content: space-between; align-items: center;
    margin-bottom: -21px;
}
.terminal-dots { display: flex; gap: 6px; }
.dot { width: 10px; height: 10px; border-radius: 50%; }
.dot-r { background: #ef4444; } .dot-y { background: #f59e0b; } .dot-g { background: #10b981; }

.narrative-payload {
    background: #090d16; border: 1px solid var(--border-color);
    border-bottom-left-radius: 12px; border-bottom-right-radius: 12px;
    padding: 32px; font-size: 15px; color: #e2e8f0; overflow-y: auto;
    min-height: 540px; line-height: 1.7;
}
.narrative-payload h3 { color: var(--accent-purple); font-size: 20px; margin-top: 0; margin-bottom: 12px; }
.narrative-payload b { color: var(--accent-blue); }
.narrative-payload hr { border: 0; border-top: 1px dashed var(--border-color); margin: 20px 0; }

/* Indikator Status */
.panel-box.locked h2::after { content: '🔒 Locked'; font-size: 11px; background: rgba(244, 63, 94, 0.1); color: var(--accent-rose); padding: 2px 8px; border-radius: 4px; margin-left: 8px; font-weight: 500; }
.panel-box.editable h2::after { content: '✍️ Editing'; font-size: 11px; background: rgba(16, 185, 129, 0.1); color: var(--accent-green); padding: 2px 8px; border-radius: 4px; margin-left: 8px; font-weight: 500; }

.toast-notif {
    position: fixed; bottom: 24px; right: 24px;
    background: var(--accent-purple); color: #ffffff; font-weight: 600;
    padding: 12px 24px; border-radius: 8px; font-size: 13px;
    box-shadow: 0 10px 25px -5px rgba(0,0,0,0.4);
    transform: translateY(100px); opacity: 0; transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    z-index: 9999;
}
.toast-notif.show { transform: translateY(0); opacity: 1; }

body.script:
//

// Array Default Karakter Dinamis
let globalCharacters = [
    { name: "Revan", role: "Protagonis (Arsitek Idealis)" },
    { name: "Mira", role: "Deuteragonis (Jurnalis Investigasi)" },
    { name: "Hendra", role: "Antagonis (Direktur Korporasi)" }
];

// Router Tab Menu Kiri
function switchTab(tabId) {
    document.querySelectorAll('.tab-panel').forEach(panel => panel.classList.remove('active'));
    document.querySelectorAll('.nav-item').forEach(btn => btn.classList.remove('active'));

    document.getElementById('panel-' + tabId).classList.add('active');
    document.getElementById('btn-tab-' + tabId).classList.add('active');

    let labelText = document.getElementById('btn-tab-' + tabId).innerText.replace(/[^\w\s]/g, '').trim();
    document.getElementById('current-mode-display').innerText = labelText;
    triggerToast("Ruang kerja: " + labelText);
}

// AKSI TOMBOL EDIT: Buka Kunci Bidang
function enableEditing(tabId) {
    let container = document.getElementById('box-' + tabId);
    container.classList.remove('locked');
    container.classList.add('editable');

    container.querySelectorAll('.form-control').forEach(input => input.removeAttribute('disabled'));
    container.querySelectorAll('.char-input-field').forEach(input => input.removeAttribute('disabled'));
    container.querySelectorAll('.btn-delete-char').forEach(btn => btn.removeAttribute('disabled'));

    if(tabId === 'character') {
        document.getElementById('btn_add_char').removeAttribute('disabled');
    }

    document.getElementById('edit-' + tabId).style.display = 'none';
    document.getElementById('save-' + tabId).style.display = 'block';
    triggerToast("Mode penyuntingan aktif.");
}

// AKSI TOMBOL SAVE: Kunci & Sinkronisasi Permanen
function savePanelData(tabId) {
    let container = document.getElementById('box-' + tabId);
    container.classList.remove('editable');
    container.classList.add('locked');

    container.querySelectorAll('.form-control').forEach(input => input.setAttribute('disabled', 'disabled'));
    container.querySelectorAll('.char-input-field').forEach(input => input.setAttribute('disabled', 'disabled'));
    container.querySelectorAll('.btn-delete-char').forEach(btn => btn.setAttribute('disabled', 'disabled'));

    if(tabId === 'character') {
        document.getElementById('btn_add_char').setAttribute('disabled', 'disabled');
        syncCharactersFromDOM();
    }

    persistToStorage();
    compileStory();
    document.getElementById('edit-' + tabId).style.display = 'block';
    document.getElementById('save-' + tabId).style.display = 'none';
    triggerToast("Data " + tabId + " berhasil disimpan!");
}

// FUNGSI DINAMIS KARAKTER: Menambahkan Baris Form Baru
function addNewCharacterRow(nameValue = "", roleValue = "") {
    let container = document.getElementById('character_container');
    let timestampId = Date.now() + Math.random().toString(36).substr(2, 5);

    let charRow = document.createElement('div');
    charRow.className = 'character-row-item';
    charRow.id = 'char-row-' + timestampId;
    charRow.innerHTML = `
        <input type="text" class="form-control char-input-field name-field" oninput="compileStory()" placeholder="Nama Tokoh" value="${nameValue}">
        <input type="text" class="form-control char-input-field role-field" oninput="compileStory()" placeholder="Peran / Karakteristik" value="${roleValue}">
        <button class="btn-delete-char" onclick="removeCharacterRow('${timestampId}')" title="Hapus Karakter">🗑️</button>
    `;

    container.appendChild(charRow);
    container.scrollTop = container.scrollHeight;
    compileStory();
}

// FUNGSI DINAMIS KARAKTER: Menghapus Baris Form Terpilih
function removeCharacterRow(id) {
    let row = document.getElementById('char-row-' + id);
    if(row) {
        row.remove();
        syncCharactersFromDOM();
        persistToStorage();
        compileStory();
        triggerToast("Satu karakter telah dihapus.");
    }
}

// Sinkronisasi data dari Elemen Input HTML ke struktur Array Objek JavaScript
function syncCharactersFromDOM() {
    let updatedList = [];
    document.querySelectorAll('.character-row-item').forEach(row => {
        let name = row.querySelector('.name-field').value.trim();
        let role = row.querySelector('.role-field').value.trim();
        if(name !== "" || role !== "") {
            updatedList.push({ name: name, role: role });
        }
    });
    globalCharacters = updatedList;
}

// Render struktur list repeater karakter ke layar UI
function renderCharacterInputs() {
    let container = document.getElementById('character_container');
    container.innerHTML = "";
    globalCharacters.forEach(char => {
        addNewCharacterRow(char.name, char.role);
    });
}

// Kompilator Generator Narasi Real-Time (Sisi Kanan)
function compileStory() {
    let title = document.getElementById('story_title').value;
    let synopsis = document.getElementById('story_synopsis').value;
    let setting = document.getElementById('story_setting').value;
    let conflict = document.getElementById('story_conflict').value;
    let style = document.getElementById('story_style').value;
    let lighting = document.getElementById('story_lighting').value;

    let currentChars = [];
    document.querySelectorAll('.character-row-item').forEach(row => {
        let name = row.querySelector('.name-field').value.trim();
        let role = row.querySelector('.role-field').value.trim();
        if(name) currentChars.push(`• <b>${name}</b>: ${role}`);
    });

    let charactersPayloadString = currentChars.length > 0 ? currentChars.join('<br/>') : '<i>Belum ada karakter yang ditambahkan</i>';

    let liveView = document.getElementById('narrative_live_view');

    liveView.innerHTML = `<h3>🔮 BUNDLE PROYEK: ${title}</h3>` +
                         `<p><i>${synopsis}</i></p>` +
                         `<hr/>` +
                         `<p><b>🎭 Arsitektur Barisan Karakter:</b><br/>${charactersPayloadString}</p>` +
                         `<p><b>🗺️ World &amp; Konflik:</b><br/>• Latar: ${setting}<br/>• Krisis Utama: ${conflict}</p>` +
                         `<p><b>🎨 Direksi Estetika:</b><br/>• Gaya: ${style}<br/>• Pencahayaan: ${lighting}</p>` +
                         `<hr/>` +
                         `<h5>Prompt Payload Hasil Kompilasi Dinamis:</h5>` +
                         `<p style="font-family: 'JetBrains Mono', monospace; font-size:13px; background: rgba(255,255,255,0.03); padding: 14px; border-radius:6px; border: 1px solid var(--border-color); white-space: pre-line;">` +
                         `Buat skenario mendalam berdasarkan proyek '${title}' yang berlatar di ${setting} dengan krisis: "${conflict}".\n\n` +
                         `Integrasikan jalinan interaksi tokoh-tokoh berikut di dalam alur:\n${currentChars.map(c => c.replace(/<\/?[^>]+(>|$)/g, "")).join('\n')}\n\n` +
                         `Visualisasikan tiap adegan secara estetis mengadopsi gaya visual ${style} serta arah skema tata cahaya ${lighting}.` +
                         `</p>`;
}

// Fitur Simpan Penyimpanan Internal Browser (LocalStorage)
function persistToStorage() {
    syncCharactersFromDOM();
    let storyData = {
        title: document.getElementById('story_title').value,
        synopsis: document.getElementById('story_synopsis').value,
        setting: document.getElementById('story_setting').value,
        conflict: document.getElementById('story_conflict').value,
        style: document.getElementById('story_style').value,
        lighting: document.getElementById('story_lighting').value,
        characters: globalCharacters
    };
    localStorage.setItem('nce_story_blueprint_v2', JSON.stringify(storyData));
}

// Muat Ulang Data dari Memori Browser saat Membuka Halaman
function loadStoredData() {
    let saved = localStorage.getItem('nce_story_blueprint_v2');
    if (saved) {
        let data = JSON.parse(saved);
        if(data.title) document.getElementById('story_title').value = data.title;
        if(data.synopsis) document.getElementById('story_synopsis').value = data.synopsis;
        if(data.setting) document.getElementById('story_setting').value = data.setting;
        if(data.conflict) document.getElementById('story_conflict').value = data.conflict;
        if(data.style) document.getElementById('story_style').value = data.style;
        if(data.lighting) document.getElementById('story_lighting').value = data.lighting;
        if(data.characters) globalCharacters = data.characters;
    }
}

// Salin Seluruh Blueprint ke Clipboard
function copyNarrative() {
    let title = document.getElementById('story_title').value;
    let synopsis = document.getElementById('story_synopsis').value;
    let setting = document.getElementById('story_setting').value;
    let conflict = document.getElementById('story_conflict').value;
    let style = document.getElementById('story_style').value;
    let lighting = document.getElementById('story_lighting').value;

    let charTextList = [];
    document.querySelectorAll('.character-row-item').forEach(row => {
        let name = row.querySelector('.name-field').value.trim();
        let role = row.querySelector('.role-field').value.trim();
        if(name) charTextList.push(`- ${name}: ${role}`);
    });

    let cleanText = `PROYEK NARASI MASTERPIECE: ${title}\n` +
                    `=====================================\n` +
                    `Sinopsis: ${synopsis}\n\n` +
                    `🎭 Daftar Karakter:\n${charTextList.join('\n')}\n\n` +
                    `Latar Tempat: ${setting}\n` +
                    `Krisis Alur: ${conflict}\n` +
                    `Gaya Seni: ${style}\n` +
                    `Pencahayaan: ${lighting}\n\n` +
                    `Prompt Siap Pakai:\nBuat skenario mendalam berdasarkan proyek '${title}' yang berlatar di ${setting} dengan krisis: "${conflict}". Jalin interaksi antar tokoh:\n${charTextList.join('\n')}\n\nVisualisasikan adegan dengan gaya seni ${style} dan pencahayaan ${lighting}.`;

    navigator.clipboard.writeText(cleanText).then(() => {
        triggerToast("Seluruh payload dan barisan karakter sukses disalin!");
    });
}

function toggleZenMode() {
    document.body.classList.toggle('zen-mode-active');
    triggerToast(document.body.classList.contains('zen-mode-active') ? "Zen Mode Aktif." : "Zen Mode Nonaktif.");
}

function triggerToast(msg) {
    let toast = document.getElementById('toastEngine');
    toast.innerText = msg;
    toast.classList.add('show');
    setTimeout(() => toast.classList.remove('show'), 2500);
}

window.onload = function() {
    loadStoredData();
    renderCharacterInputs();
    document.querySelectorAll('.char-input-field').forEach(input => input.setAttribute('disabled', 'disabled'));
    document.querySelectorAll('.btn-delete-char').forEach(btn => btn.setAttribute('disabled', 'disabled'));
    compileStory();
};
//
